56:   const before = winPercent(beforeScoreCp);
57:   const after = winPercent(-afterScoreCp);
58:   if (after >= before) return 100;
59:   const raw = ACCURACY_A * Math.exp(-ACCURACY_K * (before - after)) + ACCURACY_B + 1;
60:   return Math.min(100, Math.max(0, raw));
