294: function betweenGameGaps(games: readonly AlignedGame[]): BetweenGameGap[] {
295:   const gaps: BetweenGameGap[] = [];
296:   for (let index = 1; index < games.length; index += 1) {
297:     const previous = games[index - 1];
298:     const current = games[index];
299:     if (!previous || !current || current.startUs <= previous.endUs) continue;
300:     gaps.push({
301:       afterIndex: previous.game.index,
302:       beforeIndex: current.game.index,
303:       fromUs: previous.endUs,
304:       toUs: current.startUs,
