223:   if (cursor > stopUs) {
224:     return { ok: false, banner: 'The games are longer than the session, so they were not placed.' };
225:   }
226:   const slackUs = stopUs - cursor;
227:   const slackSec = slackUs === 0 ? 0 : Math.ceil(slackUs / 1_000_000);
