265: function rejectOutside(
266:   games: readonly AlignedGame[],
267:   clock: SessionClock,
268: ): { ok: true; games: AlignedGame[] } | { ok: false; banner: string } {
269:   const recordedStart = clock.startAnchor.monoUs;
270:   const recordedStop = clock.stopAnchor?.monoUs;
271:   const outside = games.some((game) => {
272:     if (game.endUs < game.startUs) return true;
273:     if (game.startUs < recordedStart || game.endUs < recordedStart) return true;
274:     if (recordedStop !== undefined && (game.startUs > recordedStop || game.endUs > recordedStop)) return true;
275:     return false;
276:   });
277:   if (outside) {
