283: function moveTimesFor(game: AlignedGame): MoveTime[] {
284:   const thinks = thinkTimeSec(game.game);
285:   let cursor = game.startUs;
286:   return game.game.moves.map((_move, moveIndex) => {
287:     const think = thinks[moveIndex];
288:     if (think === null || think === undefined) return { gameIndex: game.game.index, moveIndex, tUs: null };
289:     cursor += Math.round(think * 1_000_000);
