311: function traceGapsFor(game: AlignedGame, samples: readonly PulseSample[]): TraceGap[] {
312:   if (game.endUs <= game.startUs) return [];
313:   const ordered = samples
314:     .filter((sample) => {
315:       if (!usable(sample) || sample.tUs > game.endUs) return false;
316:       if (sample.tUs >= game.startUs) return true;
317:       return sample.tUs + SAMPLE_HOLD_US > game.startUs;
318:     })
319:     .sort((left, right) => left.tUs - right.tUs);
320:   const gaps: TraceGap[] = [];
321:   let cursor = game.startUs;
322:   for (const sample of ordered) {
323:     if (sample.tUs > cursor) {
324:       gaps.push({
325:         gameIndex: game.game.index,
326:         fromUs: cursor,
327:         toUs: sample.tUs,
328:         durationUs: sample.tUs - cursor,
329:       });
330:     }
331:     cursor = Math.max(cursor, Math.min(game.endUs, sample.tUs + SAMPLE_HOLD_US));
332:   }
333:   if (game.endUs > cursor) {
334:     gaps.push({
335:       gameIndex: game.game.index,
336:       fromUs: cursor,
337:       toUs: game.endUs,
338:       durationUs: game.endUs - cursor,
339:     });
340:   }
341:   return gaps;
342: }
