307: export function elevatedClaim(
308:   samples: readonly PulseSample[],
309:   startUs: number,
310:   stopUs: number,
311:   baseline: number,
312:   blunderTimes: readonly (number | null)[],
313: ): { elevatedMinutes: number; deltaBpm: number } | undefined {
314:   if (blunderTimes.length === 0 || blunderTimes.some((time) => time === null)) return undefined;
315:   const periods = elevatedPeriods(samples, startUs, stopUs, baseline);
316:   const hit = new Set<number>();
317:   for (const time of blunderTimes) {
318:     const index = periods.findIndex((period) => (time ?? -1) >= period.fromUs && (time ?? -1) <= period.toUs);
319:     if (index < 0) return undefined;
320:     hit.add(index);
321:     if (hit.size > 1) return undefined;
322:   }
323:   const period = periods[[...hit][0] ?? -1];
324:   if (!period) return undefined;
325:   return {
326:     elevatedMinutes: (period.toUs - period.fromUs) / 60_000_000,
327:     deltaBpm: Math.round(period.deltaBpm),
328:   };
