331: function elevatedPeriods(
332:   samples: readonly PulseSample[],
333:   startUs: number,
334:   stopUs: number,
335:   baseline: number,
336: ): { fromUs: number; toUs: number; deltaBpm: number }[] {
337:   const ordered = samples
338:     .filter((sample) => sample.tUs >= startUs && sample.tUs <= stopUs)
339:     .sort((left, right) => left.tUs - right.tUs);
340:   const periods: { fromUs: number; toUs: number; deltaBpm: number }[] = [];
341:   let current: { fromUs: number; toUs: number; deltaBpm: number } | undefined;
342:   for (let index = 0; index < ordered.length; index += 1) {
343:     const sample = ordered[index];
344:     if (!sample || !isUsableSample(sample, CONFIDENCE_FLOOR) || bandFor(sample.bpm, baseline) !== 'elevated') {
345:       current = undefined;
346:       continue;
347:     }
348:     const nextUs = index + 1 < ordered.length ? ordered[index + 1]?.tUs ?? stopUs : stopUs;
349:     const gap = nextUs - sample.tUs;
350:     const end = sample.tUs + (gap > 0 ? Math.min(gap, SAMPLE_HOLD_US) : 0);
351:     if (!current) {
352:       current = { fromUs: sample.tUs, toUs: end, deltaBpm: sample.bpm - baseline };
353:       periods.push(current);
354:     } else {
355:       current.toUs = end;
356:       current.deltaBpm = Math.max(current.deltaBpm, sample.bpm - baseline);
357:     }
358:     const next = ordered[index + 1];
359:     const continues =
360:       next !== undefined &&
361:       gap > 0 &&
362:       gap <= SAMPLE_HOLD_US &&
363:       isUsableSample(next, CONFIDENCE_FLOOR) &&
364:       bandFor(next.bpm, baseline) === 'elevated';
365:     if (!continues) current = undefined;
366:   }
367:   return periods;
