35: export function parsePgn(pgn: string, index: number): PgnParseResult {
36:   if (!Number.isInteger(index) || index < 0) {
37:     return invalid(index, 'The game index is not a position in the paste.');
38:   }
39:   const eventCount = pgn.match(/^\[Event\s+"/gm)?.length ?? 0;
40:   if (eventCount > 1) {
41:     return invalid(index, 'Paste one game per entry.');
42:   }
43: 
44:   const parts = splitPgn(pgn);
45:   if (parts.headers.get('FEN') !== undefined || parts.headers.get('SetUp') === '1') {
46:     return invalid(index, 'Setup positions are not accepted.');
47:   }
48:   const listed = readMoves(parts.movetext);
49:   if (!listed.ok) return invalid(index, listed.message);
50:   const headerResult = parts.headers.get('Result');
51:   if (!headerResult) return invalid(index, 'The Result tag is missing.');
52:   if (listed.result !== headerResult) {
53:     return invalid(index, 'The movetext result does not match the Result tag.');
54:   }
55: 
56:   const endDate = parts.headers.get('EndDate');
57:   const endClock = parts.headers.get('EndTime');
58:   const endTime = endClock === undefined ? undefined : epochPair(endDate, endClock);
59:   if (endTime === 'bad') return invalid(index, 'EndDate and EndTime are not a complete UTC time.');
60:   const startTime = epochPair(parts.headers.get('UTCDate'), parts.headers.get('UTCTime'));
61:   if (startTime === 'bad') return invalid(index, 'UTCDate and UTCTime are not a complete UTC time.');
62: 
63:   const ending = classifyEnding(parts.headers.get('Termination'), listed.moves);
64:   const game = {
65:     index,
66:     white: parts.headers.get('White') ?? '',
67:     black: parts.headers.get('Black') ?? '',
68:     result: headerResult,
69:     endTimeEpochMs: endTime,
70:     startTimeEpochMs: startTime,
71:     timeControl: parts.headers.get('TimeControl'),
72:     moves: listed.moves,
73:     ending,
74:     includeInStats: ending !== 'aborted' && ending !== 'abandoned',
75:   };
76:   const checked = pgnGameSchema.safeParse(game);
77:   if (!checked.success) return invalid(index, 'The parsed game does not match the game contract.');
78:   return { ok: true, game: checked.data };
