6: export function withReportExclusion<T>(operation: () => Promise<T>, signal?: AbortSignal): Promise<T> {
7:   if (signal?.aborted) return Promise.reject(cancelled());
8:   const run = queue.then(() => {
9:     // A cancelled waiter must not perform the queued file reads when its turn arrives.
10:     if (signal?.aborted) throw cancelled();
11:     return operation();
12:   });
