content.text:
Now report-ipc.ts. Need import channels/schemas, buildReport control, progress sender, cancel handler.

Current:
```ts
import { ipcMain } from 'electron';
import { reportBuildRequestSchema, reportResultSchema } from '../shared/contracts.js';
import { buildReport } from './report.js';
import { withReportExclusion } from './report-lock.js';
import { defaultDataRoot } from './store.js';

export const REPORT_BUILD_CHANNEL = 'cp:report:build';

export function registerReportHandler(dataRoot = defaultDataRoot): void {
  ipcMain.handle(REPORT_BUILD_CHANNEL, async (_event, payload) => {...});
}
```

New:
```ts
export const REPORT_PROGRESS_CHANNEL = 'cp:report:progress';
export const REPORT_CANCEL_CHANNEL = 'cp:report:cancel';

const activeBuilds = new Map<string, AbortController>(); // module-level? If register called twice, fine.

export function registerReportHandler(dataRoot = defaultDataRoot): void {
  ipcMain.handle(REPORT_BUILD_CHANNEL, async (event, payload) => {
    ...
    const { sessionId, pgns } = parsed.data;
    const controller = new AbortController();
    activeBuilds.set(sessionId, controller);
    try {
      const result = await withReportExclusion(() =>
        buildReport(dataRoot(), sessionId, pgns, undefined, {
          signal: controller.signal,
          onProgress: (progress) => {
            if (!event.sender.isDestroyed()) {
              event.sender.send(REPORT_PROGRESS_CHANNEL, reportProgressSchema.parse({ sessionId, ...progress }));
            }
          },
        }),
      );
      return reportResultSchema.parse(result);
    } finally {
      if (activeBuilds.get(sessionId) === controller) activeBuilds.delete(sessionId);
    }
  });

  ipcMain.handle(REPORT_CANCEL_CHANNEL, (_event, payload) => {
    const parsed = reportCancelRequestSchema.safeParse(payload);
    if (!parsed.success) throw new Error('Choose a session to cancel.');
    const controller = activeBuilds.get(parsed.data.sessionId);
    if (!controller) return reportCancelResultSchema.parse({ cancelled: false });
    controller.abort();
    return reportCancelResultSchema.parse({ cancelled: true });
  });
}
```

Issue: `withReportExclusion` with no signal queues; if canceled while waiting, buildReport sees aborted at start and returns cancelled. Good. But if a report build is active and a second one for the same session starts, activeBuilds overwrites; the first's finally checks identity before deleting. The first is no longer cancelable. Fine.

