     ```ts
     export interface BandLookup {
       at(tUs: number): PulseBand | null;
     }
     export function createBandLookup(samples: readonly PulseSample[], baseline: number): BandLookup {
       const ordered = [...samples].sort((a,b)=>a.tUs-b.tUs);
       return { at(tUs) { binary search ... } };
     }
     export function bandAt(samples, tUs, baseline) {
       return createBandLookup(samples, baseline).at(tUs);
     }
     ```
