it('matches the old linear lookup on unsorted, gapped, and weak samples', () => {
  const samples = [
    sample(9_000_000, 95),
    sample(1_000_000, 72),
    { tUs: 4_000_000, bpm: 60, confidence: 10, stable: true },
    sample(4_000_000, 90),
    sample(0, 70),
    sample(2_000_000, 84),
  ];
  const lookup = createBandLookup(samples, 70);
  for (const t of [0, 500_000, 1_000_000, 2_500_000, 4_000_000, 5_000_000, 6_000_000, 9_000_000, 12_000_000]) {
