function linearBandAt(samples, tUs, baseline) {
  let latest: PulseSample | undefined;
  for (const entry of samples) {
    if (entry.tUs <= tUs && (!latest || entry.tUs >= latest.tUs)) latest = entry;
  }
  if (!latest || !(latest.stable && latest.confidence >= 80)) return null;
  if (tUs > latest.tUs + SAMPLE_HOLD_US) return null;
  return latest.bpm >= baseline + 10 ? 'elevated' : 'settled';
}
