```
Add tests. Existing test loop uses fixtures. Add unit tests in `groundInsight`:
```ts
it('rejects present-tense and contracted mental-state claims', () => {
  for (const text of ['You are stressed.', "You're stressed.", 'You seem anxious.'])
    assert.throws(() => groundInsight({}, text), /diagnostic or mental-state/);
});
it('rejects a named-disease diagnosis even without the general vocabulary', () => {
  assert.throws(() => groundInsight({}, 'You have diabetes.'), /diagnostic or mental-state/);
  assert.equal(groundInsight({ baselineBpm:70 }, 'Your pulse was 70 bpm.'), 'Your pulse was 70 bpm.');
});
