    ```ts
    onEnded: (reason) => {
      if (reason !== 'storage') return;
      void stopEverything('storage').catch((error) => {
        // If the session already finalized, still tell the page why the trace ended.
        if (lastSessionId) publishToWindows(SESSION_ENDED_CHANNEL, sessionEndedSchema.parse({sessionId: lastSessionId, reason:'storage', message: ...}));
      });
    }
